DB::transaction(static function () use ($data): ?User {
            $user = User::query()->create([
                'name' => $data['name'],
                'email' => $data['email'],
                'password' => Hash::make($data['password']),
                'state' => $data['state'] ?? UserState::PENDING,
                'tenant_id' => $data['tenant_id'] ?? null,
            ]);

            // ULID is auto-generated by HasUlid trait
            // Bio can be set via translatable attributes if provided
            if (isset($data['bio'])) {
                $locale = app()->getLocale();
                $user->setTranslation('bio', $locale, $data['bio']);
                $user->save();
            }

            return $user->fresh();
        })

DB::transaction(static function () use ($user, $data): ?User {
            // Handle translatable bio field
            $locale = app()->getLocale();
            if (isset($data['bio'])) {
                // Sanitize bio before storing
                $sanitized = Purify::clean($data['bio']);
                $user->setTranslation('bio', $locale, $sanitized);
                unset($data['bio']);
            }

            // Handle password hashing if provided
            if (isset($data['password'])) {
                $data['password'] = Hash::make($data['password']);
            }

            // Handle email_verified_at reset if email changed
            $shouldResetEmailVerification =
                array_key_exists('email_verified_at', $data) && $data['email_verified_at'] === null;
            $emailChanged = isset($data['email']) && $user->email !== $data['email'];

            if ($shouldResetEmailVerification || $emailChanged) {
                unset($data['email_verified_at']);
            }

            // Update other fields
            if ($data !== []) {
                $user->update($data);
            }

            // Reset email verification if email changed
            if ($shouldResetEmailVerification || $emailChanged) {
                $user->email_verified_at = null;
                $user->save();
            }

            return $user->fresh();
        })

